define('CLI_SCRIPT',true);require '/var/www/html/config.php';require_once $CFG->dirroot.'/mod/quiz/locallib.php';$out=[];foreach(['PYAI-INTRO','PYAI-INTRO-JA'] as $sn){$c=$DB->get_record('course',['shortname'=>$sn],'*',MUST_EXIST);$ja=$sn==='PYAI-INTRO-JA';$topic=$ja?'4.1 可視化と根拠':'4.1 Visualisation and evidence';$pn=$ja?'レッスン4.1：可視化と根拠':'Lesson 4.1: Visualisation and evidence';$ln=$ja?'Python Lab 4.1：可視化と根拠':'Python Lab 4.1: Visualisation and evidence';$qn=$ja?'理解度チェック：4.1 可視化と根拠':'Knowledge check: 4.1 Visualisation and evidence';$need=$ja?['問い','一行の意味','棒グラフ','0を起点','折れ線','欠けた月','散布図','因果関係','ヒストグラム','ビン幅','タイトル','単位','色だけ','尺度','assert','savefig','観察','数値','範囲','限界']:['question','plotted grain','Bars','zero','Lines','missing periods','Scatter','causation','Histograms','Bin width','title','units','colour alone','scale','assert','savefig','observation','numbers','scope','limitation'];$sub=$DB->get_record('subsection',['course'=>$c->id,'name'=>$topic],'*',MUST_EXIST);$sec=$DB->get_record('course_sections',['course'=>$c->id,'component'=>'mod_subsection','itemid'=>$sub->id],'*',MUST_EXIST);$p=$DB->get_record('page',['course'=>$c->id,'name'=>$pn],'*',MUST_EXIST);if(substr_count($p->content,'PYAI-V26-LESSON41-FLOW')!==1)throw new RuntimeException("$sn marker");foreach($need as $n)if(!str_contains($p->content,$n))throw new RuntimeException("$sn missing $n");foreach(['Naledi','ナレディ','AI checkpoint','AI利用の確認','Teacher guide','教師用ガイド'] as $n)if(str_contains($p->content,$n))throw new RuntimeException("$sn forbidden");$q=$DB->get_record('quiz',['course'=>$c->id,'name'=>$qn],'*',MUST_EXIST);$slots=(int)$DB->count_records('quiz_slots',['quizid'=>$q->id]);if($slots!==10||abs((float)$q->sumgrades-100)>.001||(int)$q->attempts!==0||$q->grademethod!=QUIZ_GRADEHIGHEST)throw new RuntimeException("$sn quiz");$l=$DB->get_record('lti',['course'=>$c->id,'name'=>$ln],'*',MUST_EXIST);$path=$ja?'/ja/11_visualisation_evidence.ipynb':'/11_visualisation_evidence.ipynb';if(!str_ends_with($l->tool